#[IsGranted('IS_AUTHENTICATED_REMEMBERED')]final class DashboardPreferenceController extends AbstractController{#[Route('/dashboard/preferences',name:'app_dashboard_preferences',methods:['PUT'])]public function save(Request$request,EntityManagerInterface$em):JsonResponse{if(!$this->isCsrfTokenValid('dashboard_preferences',(string)$request->headers->get('X-CSRF-Token')))return$this->json(['error'=>'Token CSRF invalide.'],403);$user=$this->getUser();if(!$user instanceof User)return$this->json(['error'=>'Utilisateur invalide.'],403);$payload=json_decode($request->getContent(),true);$allowed=['attention','bank','activity','goals'];$order=array_values(array_unique(array_filter((array)($payload['order']??[]),static fn($v)=>in_array($v,$allowed,true))));foreach($allowed as$id)if(!in_array($id,$order,true))$order[]=$id;$hidden=array_values(array_filter((array)($payload['hidden']??[]),static fn($v)=>in_array($v,$allowed,true)));$collapsed=array_values(array_filter((array)($payload['collapsed']??[]),static fn($v)=>in_array($v,$allowed,true)));$user->setDashboardPreferences(compact('order','hidden','collapsed'));$em->flush();return$this->json(['saved'=>true]);}}
